mapper.select:
SELECT cr.record_id, cr.commission_no, cr.user_id, u.username, u.real_name, cr.user_type, CASE cr.user_type WHEN 1 THEN '采购员' WHEN 2 THEN '管理员' ELSE '未知' END AS user_type_name, cr.order_id, cr.order_no, cr.order_amount, cr.commission_type, CASE cr.commission_type WHEN 1 THEN '固定金额' WHEN 2 THEN '百分比' ELSE '未知' END AS commission_type_name, cr.commission_rate, cr.commission_amount, cr.commission_status, CASE cr.commission_status WHEN 0 THEN '待发放' WHEN 1 THEN '已发放' WHEN 2 THEN '已取消' ELSE '未知' END AS commission_status_name, cr.payout_time, cr.settlement_period, cr.remark, cr.created_by, cr.created_at, cr.updated_by, cr.updated_at FROM commission_record cr LEFT JOIN sys_user u ON cr.user_id = u.user_id AND u.is_deleted = 0 WHERE cr.is_deleted = 0
AND (cr.commission_no LIKE CONCAT('%', #{keyword}, '%') OR cr.order_no LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%') OR u.real_name LIKE CONCAT('%', #{keyword}, '%') OR cr.remark LIKE CONCAT('%', #{keyword}, '%'))
AND cr.user_type = #{userType}
AND cr.commission_status = #{commissionStatus}
AND cr.created_at >= #{startTime}
AND cr.created_at <= #{endTime}
AND cr.settlement_period = #{settlementPeriod}
ORDER BY cr.created_at DESC

